package io.movetodata.catalog.library.models;

import lombok.*;

import javax.persistence.*;
import java.util.UUID;

/**
 * Column-level metadata for a versioned dataset (identified by datasetId + branch).
 *
 * {@code piiType}: NULL | PII.Sensitive | GDPR.Sensitive | GDPR.ID
 */
@Entity
@NoArgsConstructor
@AllArgsConstructor
@Getter
@Setter
@Builder
@Table(
    name = "catalog_column_meta",
    uniqueConstraints = @UniqueConstraint(columnNames = {"dataset_id", "branch", "column_name"})
)
public class ColumnMeta {

    /** UUID primary key — generated by PostgreSQL gen_random_uuid(). */
    @Id
    @Column(name = "id", columnDefinition = "uuid", updatable = false, nullable = false)
    private String id;

    @Column(name = "dataset_id", nullable = false, columnDefinition = "uuid")
    private UUID datasetId;

    @Column(name = "branch", nullable = false, length = 255)
    private String branch;

    @Column(name = "column_name", nullable = false, length = 255)
    private String columnName;

    @Column(name = "description")
    private String description;

    @Column(name = "pii_type", length = 50)
    private String piiType;

    @Column(name = "retention_days")
    private Integer retentionDays;
}
